/// <summary>
/// nature 30/40 report execution class
/// </summary>
public class METNature3040ReportExecute
{
    #define.ExcelExtension('.xlsx')
    METNature3040ReportController controller;
    METNature3040ReportContract   contract;
    Filename                        fileName;

}

Method.Source:
/// <summary>
/// execute method
/// </summary>
/// <param name = "_controller">controller</param>
public static void execute(METNature3040ReportController _controller)
{
    //execute Site Specific report
    METNature3040ReportExecute siteSpecificReportExecute = new METNature3040ReportExecute_SiteSpecific();
    siteSpecificReportExecute.parmReportController(_controller);
    siteSpecificReportExecute.executeReport();

    // National report execution
    METNature3040ReportExecute nationalReportExecute = new METNature3040ReportExecute_National();
    nationalReportExecute.parmReportController(_controller);
    nationalReportExecute.executeReport();

    nationalReportExecute.updateExecutionStatus(_controller.parmReportContract().parmRdpContract() as METNature3040ReportContract);
}

/// <summary>
/// controller parm
/// </summary>
/// <param name = "_controller">controller</param>
/// <returns>controller</returns>
public METNature3040ReportController parmReportController(METNature3040ReportController _controller = null)
{
    if (_controller)
    {
        controller = _controller;
    }
    return controller;
}

/// <summary>
/// execute report
/// </summary>
public void executeReport()
{
    contract = controller.parmReportContract().parmRdpContract() as METNature3040ReportContract;
}

/// <summary>
/// generate file name for report
/// </summary>
/// <param name = "_contract">contract</param>
/// <returns>filename</returns>
public Filename generateFileName(METNature3040ReportContract    _contract)
{
    return fileName;
}

/// <summary>
/// signature to create report run contract
/// </summary>
/// <param name = "metNature3040ReportsTable">metNature3040ReportTable</param>
/// <returns>contract</returns>
public METNature3040ReportContract createReportRunContract(METNature3040ReportsTable               metNature3040ReportsTable)
{
    return contract;
}

/// <summary>
/// generate report and save to sharepoint
/// </summary>
/// <param name = "_reportRunContract">contract</param>
public void generateReportAndSaveToSharePoint(METNature3040ReportContract   _reportRunContract)
{
    SRSPrintDestinationSettings             settings;
    System.Byte[]                           reportBytes;
    SRSProxy                                srsProxy;
    SRSReportRunService                     srsReportRunService;
    Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray;
    Map                                     reportParametersMap;
    SRSReportExecutionInfo                  executionInfo;

    srsReportRunService = new SrsReportRunService();
    reportBytes = new System.Byte[0]();
    executionInfo = new SRSReportExecutionInfo();

    controller.parmReportContract().parmRdpContract(_reportRunContract);

    this.generateFileName(_reportRunContract);

    settings = controller.parmReportContract().parmPrintSettings();
    settings.printMediumType(SRSPrintMediumType::File);
    settings.fileName(fileName);
    settings.fileFormat(SRSReportFileFormat::Excel);

    controller.parmReportContract().parmReportServerConfig(SRSConfiguration::getDefaultServerConfiguration());
    controller.parmReportContract().parmReportExecutionInfo(executionInfo);

    srsReportRunService.getReportDataContract(controller.parmreportcontract().parmReportName());
    srsReportRunService.preRunReport(controller.parmreportcontract());

    reportParametersMap = srsReportRunService.createParamMapFromContract(controller.parmReportContract());
    parameterValueArray = SrsReportRunUtil::getParameterValueArray(reportParametersMap);
    srsProxy =SRSProxy::constructWithConfiguration(controller.parmReportContract().parmReportServerConfig());
    reportBytes = srsproxy.renderReportToByteArray(controller.parmreportcontract().parmreportpath(),
                                                parameterValueArray,
                                                settings.fileFormat(),
                                                settings.deviceinfo());

    System.IO.MemoryStream  mstream = new System.IO.MemoryStream(reportBytes);

    mstream.Seek(0, System.IO.SeekOrigin::Begin);

    METSharePointHelper::saveToSharepointSync(mstream, fileName, VendParameters::find().METNAT3040DocuTypeId);
}

/// <summary>
/// update Report status in report table
/// </summary>
/// <param name = "_reportRunContract">contract</param>
public void updateReportStatus(METNature3040ReportContract  _reportRunContract)
{
}

/// <summary>
/// update execution status in report execution table
/// </summary>
/// <param name = "_reportRunContract">reportRunContract</param>
public void updateExecutionStatus(METNature3040ReportContract  _reportRunContract)
{
    METNature3040ReportExecution        reportExecutionTable;
    METNature3040ReportsTable           nature3040ReportsTable;

    select firstonly RecId from nature3040ReportsTable
        where nature3040ReportsTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number()
           && nature3040ReportsTable.NationalReportGenerated == NoYes::Yes;

    if (nature3040ReportsTable.RecId)
    {
        update_recordset reportExecutionTable
            setting ReportStatus = METNAT3040ReportStatus::Success
            where reportExecutionTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number();
    }
    else 
    {
        nature3040ReportsTable = null;

        select firstonly RecId from nature3040ReportsTable
            where nature3040ReportsTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number()
            && nature3040ReportsTable.SiteSpecificReportGenerated == NoYes::No;

        if (nature3040ReportsTable.RecId)
        {
            update_recordset reportExecutionTable
                setting ReportStatus = METNAT3040ReportStatus::Failure
                where reportExecutionTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number();
        }
    }

}
